.u6-field {display:block;padding:14px 13px;color:var(--muted);font-size:12px}
.u6-field span {display:block;margin-bottom:8px}
.u6-select {display:block;width:100%;max-width:100%;min-height:44px;box-sizing:border-box;
  border:1px solid var(--line);border-radius:10px;background:var(--raised);color:var(--ink);padding:9px;font:inherit;font-size:13px}
.u6-line {border-top:1px solid var(--line);padding:14px 13px}
.u6-line .u6-hint {margin:0}
.u6-hud-head {display:flex;justify-content:space-between;align-items:center;gap:10px;padding:14px 13px}
.u6-diagnostics small {color:var(--muted);font-size:12px;line-height:1.5}
.u6-diagnostics input:disabled {opacity:.5}
.u6-card [data-error="true"] {color:#ffb9af}
</style>
<style>*[hidden] {display:none!important}
html,body {margin:0;background:#0d1715;color:#edf5f1;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif}
#u6-stage {
    --ink:#edf4f1;--muted:#a1b8af;--green:#9ee6c6;--line:#29423a;
    --panel:#15231f;--raised:#1c332a;--base:#101b18;
    max-width:460px;margin:10px auto;box-sizing:border-box;padding:18px 15px 10px;
    background:var(--base);border:1px solid var(--line);border-radius:22px;
}
#u6-stage * {box-sizing:border-box}
.u6-eyebrow {color:var(--muted);font-size:12px;text-align:right;margin-bottom:7px}
.u6-header h1 {font-size:clamp(20px,6vw,28px);line-height:1.26;margin:0 0 16px;letter-spacing:-.025em}
.u6-device {display:flex;align-items:center;gap:11px;border:1px solid #2b4a3e;background:#163027;border-radius:15px;padding:12px}
.u6-glyph {flex:0 0 38px;height:38px;display:grid;place-items:center;color:var(--green);background:#214537;border-radius:11px}
.u6-glyph svg {width:23px;height:23px}
.u6-device-text {flex:1;min-width:0}
.u6-device-text strong,.u6-device-text small {display:block;overflow-wrap:anywhere}
.u6-device-text small,.u6-diagnostics small {font-size:12px;color:var(--muted)}
.u6-chip {font-size:11px;color:var(--green);background:#204235;padding:4px 7px;border-radius:999px;white-space:nowrap}
.u6-chip[data-state="error"] {color:#ffb9b0;background:#482d27}
.u6-tabs {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;padding:4px;border:1px solid var(--line);background:#12201b;border-radius:13px;margin:14px 0}
.u6-tabs button {border:0;min-height:42px;border-radius:9px;background:none;color:var(--muted);font:inherit;font-size:13px;font-weight:600}
.u6-tabs button[aria-pressed="true"] {background:#204136;color:var(--green)}
#u6-stage h2,#u6-stage .title {font-size:14px;line-height:1.5;background:none;color:var(--muted);font-weight:600;padding:0;margin:18px 3px 9px}
#u6-stage .weui-cell {background:var(--panel);color:var(--ink);padding:11px 12px;min-height:47px;border-inline:1px solid var(--line)}
#u6-stage .weui-cell:before {border-color:var(--line);right:12px;transform:none}
#u6-stage .weui-cell__ft {color:var(--green);margin-left:10px;overflow-wrap:anywhere}
#u6-stage .title + .weui-cell {border-top:1px solid var(--line);border-radius:12px 12px 0 0}
#u6-stage .cells > .weui-cell:last-child {border-bottom:1px solid var(--line);border-radius:0 0 12px 12px}
#u6-stage .weui-panel {padding:8px 0;margin:0;color:var(--muted);background:transparent}
#u6-stage .weui-panel:before,#u6-stage .weui-panel:after {display:none}
#u6-stage .weui-loadmore {margin:12px 0 15px;width:auto;text-align:left}
#u6-stage #txt11 {color:var(--muted);font-size:13px}
#u6-stage .weui-btn {background:var(--raised);color:var(--green);font-size:14px;border-radius:10px}
.u6-card {background:var(--panel);border:1px solid var(--line);border-radius:14px;margin-bottom:14px}
.u6-nav-card {padding:13px}
.u6-diagnostics {padding:13px;display:flex;align-items:center;justify-content:space-between;gap:12px}
.u6-diagnostics small {display:block;margin-top:3px}
.u6-diagnostics input {appearance:none;flex:0 0 43px;height:25px;border-radius:999px;background:#32453d;position:relative}
.u6-diagnostics input::before {content:"";position:absolute;width:19px;height:19px;border-radius:100%;background:#e1ece6;top:3px;left:3px}
.u6-diagnostics input:checked {background:#388767}
.u6-diagnostics input:checked::before {left:21px}
.u6-hint {color:var(--muted);font-size:12px;line-height:1.6;margin:9px 12px 11px;overflow-wrap:anywhere}
.u6-nav-card .u6-hint {margin-left:0;margin-right:0}
.u6-actions {border-top:1px solid var(--line);padding:12px;display:flex;gap:8px;flex-wrap:wrap}
.u6-button {background:var(--raised);color:var(--ink);border:1px solid var(--line);border-radius:10px;
    min-height:44px;padding:9px 12px;font:inherit;font-size:13px;font-weight:600;display:inline-flex;align-items:center}
.u6-button:disabled {opacity:.55}
.u6-button[aria-pressed="true"] {color:var(--green);border-color:#388767}
.u6-test-controls {display:flex;flex-wrap:wrap;gap:8px;padding:0 13px 13px}
.u6-test-card > p {margin:8px 13px 12px}
.u6-danger {color:#ffb9af}
.u6-card details {border-top:1px solid var(--line);padding:12px}
.u6-card details summary {cursor:pointer;color:var(--ink)}
.u6-card pre {color:#c4d9d1;white-space:pre-wrap;overflow-wrap:anywhere;max-height:310px;overflow:auto;margin-top:12px;font-size:11px}
.u6-counts {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border:1px solid var(--line);border-radius:10px;overflow:hidden;margin:13px 0}
.u6-counts div {min-width:0;text-align:center;padding:9px 0}
.u6-counts div+div {border-left:1px solid var(--line)}
.u6-counts strong,.u6-counts span {display:block;overflow-wrap:anywhere}
.u6-counts strong {color:var(--green);font-size:19px}
.u6-counts span {color:var(--muted);font-size:12px}
#u6-stage footer {text-align:center;color:var(--muted);font-size:11px;border-top:1px solid var(--line);padding:11px 0 2px;margin-top:18px}
@media(max-width:490px) {#u6-stage{margin:9px;max-width:none}}
</style>
